BLOCK_MARKERS = ('access to this page requires this annoying captcha', 'verify you are human', 'enable javascript and cookies to continue')

def unwrap_wayback(url: str) -> tuple[str, str | None]:
    match = re.match('https?://web\\.archive\\.org/web/([^/]+)/(.+)$', url)
    if not match:
        return (url, None)
    return (match.group(2), match.group(1))

def canonicalize_url(url: str) -> str:
    target, _ = unwrap_wayback(url)
    parts = urlsplit(target)
    hostname = (parts.hostname or '').lower()
    if hostname.startswith('www.'):
        hostname = hostname[4:]
    port = parts.port
    netloc = hostname
    if port and (not (parts.scheme == 'http' and port == 80 or (parts.scheme == 'https' and port == 443))):
        netloc = f'{hostname}:{port}'
    path = re.sub('/{2,}', '/', parts.path)
    if path != '/':
        path = path.rstrip('/')
    query = urlencode(sorted(parse_qsl(parts.query, keep_blank_values=True)))
    return urlunsplit(('https', netloc, path, query, ''))

def apply_facet_rules(text: str) -> tuple[dict[str, list[str]], dict[str, dict[str, list[str]]]]:
    lowered = text.lower()
    facets: dict[str, list[str]] = {}
    evidence: dict[str, dict[str, list[str]]] = {}
    for facet, tag_rules in FACET_RULES.items():
        facets[facet] = []
        evidence[facet] = {}
        for tag, patterns in tag_rules.items():
            matches = []
            for pattern in patterns:
                match = re.search(pattern, lowered, re.IGNORECASE)
                if match:
                    matches.append(match.group(0))
            if matches:
                facets[facet].append(tag)
                evidence[facet][tag] = sorted(set(matches))
        facets[facet].sort()
    return (facets, evidence)

def content_quality(text: str | None, source_kind: str | None=None) -> tuple[str, list[str]]:
    if text is None:
        return ('unavailable', [])
    lowered = text.lower()
    flags = [marker for marker in BLOCK_MARKERS if marker in lowered]
    if len(text) < 1200 and 'access denied' in lowered[:500]:
        flags.append('access denied')
    if flags:
        return ('blocked_or_noise', flags)
    minimum_characters = 300 if source_kind == 'curated_markdown_copy' else 1200
    if len(text) < minimum_characters:
        return ('short', [f'content_under_{minimum_characters}_characters'])
    return ('usable', [])

def preferred_variant(variants: list[dict]) -> dict | None:
    if not variants:
        return None
    priority = {'curated_markdown_copy': 0, 'scraped_text': 1}
    return sorted(variants, key=lambda item: (priority.get(item['kind'], 9), -len(item['text'])))[0]
